import csv
files = ["ae_ci.csv","ae_death.csv","ae_tpd.csv","ae_ip.csv"]
for f in files:
    print("="*30, f)
    try:
        with open(f) as fh:
            rows = list(csv.reader(fh))
    except Exception as e:
        print("ERR", e); continue
    for row in rows[:60]:
        print("\t".join(str(x) for x in row))
    if len(rows) > 60:
        print("...", len(rows), "rows total")
